#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

const int MAXN = 200;
const int MAXM = 100000;
const int INF = 99999999;

int grid[20][20];
int adj[MAXN][MAXN];
int n, totalNodes, t;
string line;
int startPoints[MAXN][3], endPoints[MAXN][3];
int zr, zc;
int cX, cY;
int dir[4][2] = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};

int indexOf(int r, int c) {
    if (r > 0 && r <= n && c > 0 && c <= n && grid[r][c] != -1)
        return (r - 1) * n + c;
    return -1;
}

void createGraph() {
    totalNodes = n * n;
    memset(adj, -1, sizeof(adj));
    for (int r1 = 1; r1 <= n; r1++) {
        for (int c1 = 1; c1 <= n; c1++) {
            if (grid[r1][c1] == -1) continue;
            int p1 = (r1 - 1) * n + c1;
            adj[p1][p1] = 0;
            for (int i = 0; i < 4; i++) {
                int r2 = r1 + dir[i][0];
                int c2 = c1 + dir[i][1];
                if (r2 > 0 && r2 <= n && c2 > 0 && c2 <= n && grid[r2][c2] != -1) {
                    int p2 = (r2 - 1) * n + c2;
                    adj[p1][p2] = 1;
                }
            }
        }
    }
}

int distances[MAXN];
int q[MAXM];

void computeDistances() {
    int front = 0, rear = 1;
    for (int i = 1; i <= totalNodes; i++) distances[i] = INF;
    int s = (zr - 1) * n + zc;
    distances[s] = 0;
    q[0] = s;
    while (front < rear) {
        int u = q[front++];
        for (int v = 1; v <= totalNodes; v++) {
            if (adj[u][v] == 1 && distances[v] > distances[u] + 1) {
                distances[v] = distances[u] + 1;
                q[rear++] = v;
            }
        }
    }
}

void floydAllPairs() {
    for (int k = 1; k <= totalNodes; k++) {
        for (int i = 1; i <= totalNodes; i++) {
            for (int j = 1; j <= totalNodes; j++) {
                if (adj[i][k] != -1 && adj[k][j] != -1) {
                    if (adj[i][j] == -1 || adj[i][j] > adj[i][k] + adj[k][j]) {
                        adj[i][j] = adj[i][k] + adj[k][j];
                    }
                }
            }
        }
    }
}

struct Edge {
    int from, to, cap, next;
};

vector<Edge> flowEdges;
int head[MAXN], edgeIdx;
int sNode, tNode;

void addFlowEdge(int u, int v, int cap) {
    flowEdges.push_back({u, v, cap, head[u]});
    head[u] = (int)flowEdges.size() - 1;
    flowEdges.push_back({v, u, 0, head[v]});
    head[v] = (int)flowEdges.size() - 1;
}

int level[MAXN];

bool buildLevelGraph() {
    memset(level, -1, sizeof(level));
    level[sNode] = 0;
    queue<int> q;
    q.push(sNode);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = flowEdges[i].next) {
            int v = flowEdges[i].to;
            if (flowEdges[i].cap > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[tNode] != -1;
}

int ptr[MAXN];

int sendFlow(int u, int flow) {
    if (u == tNode) return flow;
    for (int &i = ptr[u]; i != -1; i = flowEdges[i].next) {
        int v = flowEdges[i].to;
        if (flowEdges[i].cap > 0 && level[v] == level[u] + 1) {
            int pushed = sendFlow(v, min(flow, flowEdges[i].cap));
            if (pushed > 0) {
                flowEdges[i].cap -= pushed;
                flowEdges[i ^ 1].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (buildLevelGraph()) {
        for (int i = 0; i <= totalNodes + 1; i++) ptr[i] = head[i];
        while (int pushed = sendFlow(sNode, INF))
            totalFlow += pushed;
    }
    return totalFlow;
}

int solve() {
    grid[zr][zc] = 0;
    createGraph();
    computeDistances();
    grid[zr][zc] = -1;
    createGraph();
    floydAllPairs();
    flowEdges.clear();
    memset(head, -1, sizeof(head));
    edgeIdx = 0;
    sNode = 0;
    tNode = cX + cY + 1;
    for (int i = 1; i <= cX; i++) {
        addFlowEdge(sNode, i, hu[i][2]);
    }
    for (int i = 1; i <= cY; i++) {
        addFlowEdge(cX + i, tNode, re[i][2]);
    }
    int p = (zr - 1) * n + zc;
    for (int i = 1; i <= cX; i++) {
        for (int j = 1; j <= cY; j++) {
            int p1 = (hu[i][0] - 1) * n + hu[i][1];
            int p2 = (re[j][0] - 1) * n + re[j][1];
            if (adj[p1][p2] != -1 && adj[p1][p2] <= t && adj[p1][p2] < distances[p2]) {
                addFlowEdge(i, cX + j, INF);
            } else if (adj[p1][p2] != -1 && adj[p1][p2] <= t && adj[p1][p2] == distances[p2]) {
                for (int z = 0; z < 4; z++) {
                    int rr = re[j][0] + dir[z][0];
                    int cc = re[j][1] + dir[z][1];
                    int pp = indexOf(rr, cc);
                    if (pp != -1) {
                        if (adj[p1][pp] == adj[p1][p2] - 1 && adj[p1][pp] < distances[pp]) {
                            addFlowEdge(i, cX + j, INF);
                        }
                    }
                }
            }
        }
    }
    return maxFlow();
}

int main() {
    cin >> n >> t;
    cX = cY = 0;
    memset(grid, 0, sizeof(grid));
    for (int i = 1; i <= n; i++) {
        cin >> line;
        for (int j = 0; j < n; j++) {
            if (line[j] == 'Y') grid[i][j + 1] = -1;
            else if (line[j] == 'Z') {
                zr = i; zc = j + 1;
                grid[i][j + 1] = -1;
            } else if (line[j] > '0' && line[j] <= '9') {
                hu[++cX][0] = i;
                hu[cX][1] = j + 1;
                hu[cX][2] = line[j] - '0';
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        cin >> line;
        for (int j = 0; j < n; j++) {
            if (line[j] > '0' && line[j] <= '9') {
                re[++cY][0] = i;
                re[cY][1] = j + 1;
                re[cY][2] = line[j] - '0';
            }
        }
    }
    cout << solve() << endl;
    return 0;
}
